// Parity test: our vendored payroll engine must reproduce, to the last
// floating-point digit, what the ORIGINAL Payroll-Sys-2026 code (@ 1feaee25,
// xlsx 0.18.5) produced for the same anonymized workbooks and adjustments.
// __fixtures__/golden.json was generated by running the untouched upstream
// source (see __fixtures__/README.md); never hand-edit it.
import { readFileSync } from "node:fs"
import { join } from "node:path"
import { describe, expect, it } from "vitest"
import { parseWorkbook } from "./excel-parser"
import { buildRuleSnapshot, computePayrollRun } from "./run"
import { calculateExpensesFromList, resolveActiveDriverCount, type ExpenseInput } from "./income-engine"

const FX = join(__dirname, "__fixtures__")
type Scenario = { id: string; workbook: string; payrollMonth: string; rules: Record<string, unknown>; sources: Record<string, Array<Record<string, unknown>>>; expenses: ExpenseInput[] }
const scenarios = JSON.parse(readFileSync(join(FX, "scenarios.json"), "utf8")) as Scenario[]
const golden = JSON.parse(readFileSync(join(FX, "golden.json"), "utf8")) as Record<string, Record<string, unknown>>
const ids = (v: unknown) => (typeof v === "string" ? (JSON.parse(v) as string[]) : [])
// JSON round-trip so `undefined`/-0 normalisation matches the stored golden output.
const plain = <T,>(v: T): T => JSON.parse(JSON.stringify(v)) as T

describe.each(scenarios)("payroll engine parity — $id", sc => {
  const parsed = parseWorkbook(readFileSync(join(FX, sc.workbook)))
  const sources = {
    customBonuses: (sc.sources.customBonuses ?? []).map(b => ({ ...b, targetRiderIds: ids(b.targetRiderIds) })) as never,
    customDeductions: (sc.sources.customDeductions ?? []).map(d => ({ ...d, targetRiderIds: ids(d.targetRiderIds) })) as never,
    manualAdjustments: (sc.sources.manualAdjustments ?? []) as never,
    trafficViolations: (sc.sources.trafficViolations ?? []) as never,
  }
  const run = computePayrollRun({ rawDrivers: parsed.drivers, parserWarnings: parsed.warnings, rules: buildRuleSnapshot(sc.rules), ruleSetName: "Golden rules", payrollMonth: sc.payrollMonth, sources, advanceInstallments: true })
  // eslint-disable-next-line @typescript-eslint/no-explicit-any -- golden JSON shape
  const g = golden[sc.id] as Record<string, any>

  it("parses the workbook identically", () => {
    expect(plain({ warnings: parsed.warnings, banking: parsed.banking, driverBanking: parsed.driverBanking, sheetNames: parsed.sheetNames, riderCount: parsed.drivers.length })).toEqual(g.parsed)
  })
  it("calculates every rider identically", () => {
    expect(plain(run.riders.map(r => r.result))).toEqual(g.results)
  })
  it("produces identical totals, exceptions and income rows", () => {
    expect(plain(run.totals)).toEqual(g.totals)
    expect(plain(run.exceptions)).toEqual(g.exceptions)
    expect(plain(run.incomeRows)).toEqual(g.incomeRows)
  })
  it("allocates expenses identically", () => {
    const count = resolveActiveDriverCount({ confirmedCount: run.riders.length })
    expect(count).toBe(g.activeDriverCount)
    expect(plain(run.riders.map(r => ({ riderId: r.result.riderId, ...calculateExpensesFromList(sc.expenses, r.result.riderId, count) })))).toEqual(g.expenseAllocations)
  })
  it("advances installments identically", () => {
    const after = g.installmentsAfter as { customDeductions: Array<{ id: string }>; trafficViolations: Array<{ id: string }> }
    const apply = (rows: Array<Record<string, unknown>>, changes: Array<{ id: string }>) => rows.map(r => ({ id: r.id, installmentTotalPaid: r.installmentTotalPaid, installmentStatus: r.installmentStatus, ...changes.find(c => c.id === r.id) }))
    expect(apply(sc.sources.customDeductions ?? [], run.installments.customDeductions)).toEqual(after.customDeductions)
    expect(apply(sc.sources.trafficViolations ?? [], run.installments.trafficViolations)).toEqual(after.trafficViolations)
  })
})
